const $=s=>document.querySelector(s),KEY='lived-history-v1';
let raw=null;
try{raw=JSON.parse(localStorage.getItem(KEY))}catch{}
let state=migrateSave(raw),screen='home',studyTab='review',quizMode='story',reviewQuestionId=null,reviewAnswer=null,modal=null,resultChapterId=null,showAllChapters=false;
const imageCache=new Map();
let cinematicTimer=null,inputLockedUntil=0;
const statNames={health:'체력',knowledge:'지식',fame:'명성',wealth:'재산'};
const relationNames={doyun:'도윤',village:'마을 주민',merchant:'상단',royal:'왕건 세력',citizens:'개경 백성',hyunwoo:'현우'};
const run=()=>state.run,mainRun=()=>state.mainRun||state.run,meta=()=>state.meta;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const chapter=()=>CHAPTERS[run().currentChapter||'ch01'];
const mainChapter=()=>CHAPTERS[mainRun().currentChapter||'ch01']||CHAPTERS.ch01;
const chapterOrder=()=>Object.values(CHAPTERS).sort((a,b)=>Number(a.number)-Number(b.number));
const chapterScenes=id=>Object.values(STORIES).filter(s=>(s.chapterId||'ch01')===id);
const chapterQuestions=id=>QUESTIONS.filter(q=>q.chapterId===id);
const progressFor=r=>{const scenes=chapterScenes(r.currentChapter);return r.completed?100:scenes.length?Math.min(96,Math.round((r.visited||[]).filter(id=>(STORIES[id]?.chapterId||'ch01')===r.currentChapter).length/scenes.length*100)):0};
const progress=()=>progressFor(run());
const correctFor=(r,chapterId=r.currentChapter)=>chapterQuestions(chapterId).filter(q=>r.questionResults?.[q.questionId]).length;
const currentCorrect=()=>correctFor(run());
const cumulativeAccuracy=()=>{const records=Object.values(meta().questionRecords),attempts=records.reduce((n,r)=>n+r.attempts,0),correct=records.reduce((n,r)=>n+r.correctCount,0);return attempts?Math.round(correct/attempts*100):0};
function chapterStatus(id){if(meta().completedChapters.includes(id))return'COMPLETED';const order=chapterOrder(),index=order.findIndex(item=>item.chapterId===id),previous=index<=0||meta().completedChapters.includes(order[index-1].chapterId),main=mainRun();if(main.currentChapter===id&&!main.completed)return'CURRENT';if(previous&&!meta().completedChapters.includes(id)&&!order.slice(0,index).some(item=>!meta().completedChapters.includes(item.chapterId)))return'CURRENT';return'LOCKED'}
function chapterProgress(id){if(chapterStatus(id)==='COMPLETED')return 100;const main=mainRun();return main.currentChapter===id?progressFor(main):0}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{toast('저장 공간을 사용할 수 없습니다. 브라우저 설정을 확인해 주세요.')}}
function toast(t){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.append(el);setTimeout(()=>el.remove(),2600)}

function icon(name){const paths={home:'<path d="M3 10.5 10 4l7 6.5v7H6v-7"/>',era:'<circle cx="10" cy="10" r="7"/><path d="M10 3v14M3 10h14"/>',study:'<path d="M4 4h5a2 2 0 0 1 2 2v11a2 2 0 0 0-2-2H4zM16 4h-3a2 2 0 0 0-2 2v11a2 2 0 0 1 2-2h3z"/>',records:'<path d="M4 17V9m6 8V3m6 14v-5"/>',lock:'<rect x="5" y="9" width="10" height="8" rx="2"/><path d="M7 9V7a3 3 0 0 1 6 0v2"/>'};return `<svg class="icon" viewBox="0 0 20 20" aria-hidden="true">${paths[name]||paths.home}</svg>`}
function shell(content){const tab=['game','quiz','complete','teaser','history'].includes(screen)?'home':screen;return `<div class="shell"><aside class="sidebar"><div class="brand">살아본 한국사<small>HISTORY, LIVED.</small></div><nav class="nav" aria-label="주 메뉴">${[['home','홈'],['era','시대'],['study','공부'],['records','내 기록']].map(([id,label])=>`<button data-nav="${id}" class="${tab===id?'active':''}">${icon(id)}<span>${label}</span></button>`).join('')}</nav><div class="sidebar-foot"><b>역사 속, 나의 이야기</b>외우는 역사에서<br>살아보는 역사로.<br><span>EPISODE 01 · GORYEO</span></div></aside><main class="main fade">${content}</main></div>${modal?modalHTML():''}`}
function pageHeader(title,sub='YOUR HISTORY, YOUR STORY'){return `<header class="topbar"><div><div class="eyebrow">${sub}</div><h1>${title}</h1></div><div class="toptools"><span>나의 첫 번째 역사 여행</span><button class="avatar" data-action="status" aria-label="내 상태 보기">나</button></div></header>`}
function assetStyle(assetId){const a=ASSETS[assetId]||ASSETS['home-goryeo'];return a.src?`background-image:url('${a.src}')`:`--scene-a:${a.palette?.[0]||'#263640'};--scene-b:${a.palette?.[1]||'#8b6d4b'}`}
function assetNotice(assetId,compact=false){const a=ASSETS[assetId]||ASSETS['home-goryeo'];if(a.status!=='ASSET_REQUIRED')return '';return `<div class="asset-required ${compact?'compact':''}"><span>ASSET_REQUIRED</span><b>${esc(assetId)}</b><small>${esc(a.label)}</small></div>`}
function resolvedPortraitId(entry){if(!entry?.portrait)return null;if(entry.characterId==='player'){const outfit=run().playerOutfit||(run().flags.wearingModernClothes===false?'goryeo_commoner':'modern'),map=CHARACTER_ASSET_MAP.player.outfits[outfit]||CHARACTER_ASSET_MAP.player.outfits.modern;return map[entry.expression]||map.neutral||entry.portrait}const characterMap=CHARACTER_ASSET_MAP[entry.characterId],characterState=run().characterStates?.[entry.characterId]||{};if(characterMap?.ages){const age=characterMap.ages[characterState.ageVariant]||characterMap.ages[characterMap.defaultAge],outfit=characterState.outfit||age.defaultOutfit,map=age.outfits[outfit]||age.outfits[age.defaultOutfit];return map?.[entry.expression]||map?.neutral||entry.portrait}return entry.portrait}
function preloadImage(src){if(!src||imageCache.has(src))return imageCache.get(src)||Promise.resolve();if(typeof Image==='undefined'){const ready=Promise.resolve(src);imageCache.set(src,ready);return ready}const promise=new Promise(resolve=>{const img=new Image();img.onload=img.onerror=()=>resolve(src);img.src=src});imageCache.set(src,promise);return promise}
function sceneAssetUrls(sceneId){const source=STORIES[sceneId];if(!source)return[];const urls=[],art=ASSETS[source.illustrationId];if(art?.src&&source.sceneEffect!=='blackout')urls.push(art.src);for(const entry of source.dialogues||[]){const portrait=PORTRAITS[resolvedPortraitId(entry)];if(portrait?.src)urls.push(portrait.src)}for(const c of source.choices||[]){const resultArt=ASSETS[c.resultIllustrationId];if(resultArt?.src)urls.push(resultArt.src);for(const entry of c.resultDialogues||[]){const portrait=PORTRAITS[resolvedPortraitId(entry)];if(portrait?.src)urls.push(portrait.src)}}return[...new Set(urls)]}
function preloadScene(sceneId){const source=STORIES[sceneId];sceneAssetUrls(sceneId).forEach(preloadImage);if(source?.nextStoryId)sceneAssetUrls(source.nextStoryId).forEach(preloadImage);for(const c of source?.choices||[])sceneAssetUrls(c.nextStoryId).forEach(preloadImage)}
function preloadChapterCore(chapterId){const characterIds=['ch02','ch03'].includes(chapterId)?new Set(['player','doyun','hyunwoo','merchant']):new Set(['player','doyun','stranger']);Object.values(PORTRAITS).filter(asset=>asset.src&&characterIds.has(asset.characterId)).forEach(asset=>preloadImage(asset.src));preloadScene(CHAPTERS[chapterId]?.startStoryId)}
function lockInput(ms=160){const now=Date.now();if(now<inputLockedUntil)return false;inputLockedUntil=now+ms;return true}

function latestRunRecord(id){const record=meta().chapterRecords[id];return record?.latestRun||meta().chapterRuns[id]?.at(-1)||record}
function chapterRow(id){const info=CHAPTERS[id],status=chapterStatus(id),record=latestRunRecord(id),pct=chapterProgress(id),main=mainRun(),choiceCount=record?.choices?.length||0,previous=chapterOrder()[Math.max(0,chapterOrder().findIndex(item=>item.chapterId===id)-1)],description=status==='COMPLETED'?`완료한 이야기 · ${choiceCount}개의 선택`:status==='CURRENT'?(info.implemented?(main.currentChapter===id&&main.started?`진행 중 · ${pct}%`:'다음으로 플레이할 이야기'):'다음 이야기 · 준비 중'):`${previous?.number?'CH.'+previous.number+'을':'이전 챕터를'} 완료하면 열립니다.`,statusControl=status==='COMPLETED'?`<button class="chapter-result badge" data-chapter-result="${id}" aria-label="CH.${info.number} 결과 바로 보기">결과 보기 <b>›</b></button>`:`<span class="badge chapter-state">${status==='CURRENT'?(pct?'현재 진행':'현재 이야기'):`${icon('lock')} 잠김`} <b>›</b></span>`;return `<article class="chapter-line chapter-${status.toLowerCase()}" data-status="${status}"><button class="chapter-card-hit" data-chapter="${id}" aria-label="CHAPTER ${info.number} ${esc(info.subtitle)} ${status==='LOCKED'?'잠금 안내':'상세 보기'}"></button><img class="chapter-thumb" src="${esc(info.thumbnail||'goryeo.png')}" alt=""><div class="chapter-copy"><small>CHAPTER ${info.number} · ${esc(info.title)}</small><h3>${esc(info.subtitle)}</h3><p>${esc(description)}</p><div class="progress" aria-label="진행률 ${pct}%"><span style="width:${pct}%"></span></div></div>${statusControl}</article>`}
function home(){const r=mainRun(),hasSave=r.started,all=chapterOrder(),visible=showAllChapters?all:all.slice(0,3),replayActive=Boolean(state.mainRun),heroAction=replayActive?'current-main':'play',heroLabel=replayActive?'현재 이야기 이어하기':hasSave?(r.completed?'챕터 결과 보기':'이야기 이어하기'):'이야기 시작하기';return pageHeader('오늘은 어떤 역사를 살아볼까요?')+`<section class="hero"><div class="hero-content"><span class="pill">EPISODE 01 · 918 — 1392</span><h2><span>눈떠보니</span>고려</h2><p>새 나라의 탄생을 지나, 왕의 힘이 자라나는 고려를 살아갑니다.</p><div class="hero-bottom"><button class="primary" data-action="${heroAction}">${heroLabel}</button>${hasSave&&!replayActive?'<button class="secondary" data-action="restart-current">현재 챕터 다시하기</button>':''}<small>CH.${mainChapter().number} &nbsp; ${esc(mainChapter().subtitle)}</small></div></div><span class="hero-mark">당신의 선택이 역사가 되는 순간</span></section><div class="home-grid"><section><div class="section-title"><h2>나의 고려 이야기</h2><button class="text-btn" data-nav="records">기록 보기 &nbsp; ›</button></div><div class="chapter-list">${visible.map(info=>chapterRow(info.chapterId)).join('')}</div>${all.length>3?`<button class="chapter-list-toggle" data-action="toggle-chapters">${showAllChapters?'잠긴 챕터 접기':'앞으로의 챕터 '+(all.length-3)+'개 보기'} <b>${showAllChapters?'⌃':'⌄'}</b></button>`:''}<div class="section-title home-understanding"><h2>시대별 이해도</h2><span class="text-btn">차근차근, 역사를 내 것으로</span></div><div class="era-strip">${ERAS.map(([name],i)=>`<div class="era-item"><b>${name}</b><small>${i===0?cumulativeAccuracy():0}%</small><div class="progress"><span style="width:${i===0?cumulativeAccuracy():0}%"></span></div></div>`).join('')}</div></section><aside class="review"><span class="eyebrow">${meta().wrongQuestionIds.length?'TODAY’S REVIEW':'A MOMENT TO REMEMBER'}</span><h3>${meta().wrongQuestionIds.length?'다시 만나면,<br>더 오래 기억하니까.':'살아본 순간이,<br>나의 지식이 되도록.'}</h3><p>${meta().wrongQuestionIds.length?`복습할 역사 ${meta().wrongQuestionIds.filter(id=>!meta().reviewedQuestionIds.includes(id)).length}개가 기다리고 있어요.`:'이야기에서 경험한 사건이<br>시험 문제와 자연스럽게 이어집니다.'}</p><button data-nav="study">${meta().wrongQuestionIds.length?'오늘의 복습 시작':'나의 학습 기록'}</button>${meta().completedChapters.includes('ch01')&&!meta().completedChapters.includes('ch02')?'<button class="start-chapter" data-action="start-ch02">CH.02 시작하기</button>':''}</aside></div><footer class="bottom-note"><span>선택하고, 살아보고, 기억하는 한국사.</span><span>진행 상황은 이 기기에 자동 저장됩니다.</span></footer>`}
function eras(){const main=mainRun();return pageHeader('당신이 살아갈 시대','CHOOSE YOUR ERA')+`<p class="lead">한 시대의 시작에서, 나만의 이야기를 만나세요.</p><div class="era-list">${ERAS.map(([name,years],i)=>`<section class="era-card"><span class="eyebrow">EPISODE 0${i+1}</span><h2>눈떠보니 ${name}</h2><p>${years}</p>${i===0?`<div class="era-actions"><button class="primary" data-action="${state.mainRun?'current-main':'play'}">${main.started?'이야기 이어하기':'이야기 시작하기'}</button>${main.started?'<button class="secondary" data-action="restart-episode">처음부터 다시하기</button>':''}</div>`:`<span class="badge">${icon('lock')} &nbsp; COMING SOON</span>`}</section>`).join('')}</div>`}
function enterStory(){const r=run(),id=r.storyId,dialogueKey=r.pending?`result:${r.pending.sourceSceneId}`:id;if(r.dialogueSceneId!==dialogueKey){r.dialogueSceneId=dialogueKey;r.dialogueCursor=1}if(!r.pending){applySceneEntry(state,id);applyDialogueMilestone(state,id,r.dialogueCursor)}if(STORIES[id]&&!r.visited.includes(id))r.visited.push(id);const add=(list,value)=>{if(!list.includes(value))list.push(value)};if(id==='village')add(meta().achievements,'time-traveler');if(id==='outfit_gift'){add(r.sharedEvents,'met_doyun_ch01');add(meta().people,'도윤')}if(id==='rumor')add(meta().people,'왕건');if(id==='foundation'){add(meta().historicalEvents,'goryeo-foundation-918');add(meta().cards,'goryeo-foundation-918')}if(id==='market'||id==='doyun'){add(meta().people,'궁예');add(meta().people,'견훤')}if(id==='ch02_market')add(meta().people,'광종');if(id==='ch02_inspection'){add(meta().historicalEvents,'gwangjong-956-nobi');add(meta().cards,'nobi-inspection')}if(id==='ch02_exam_notice'){add(meta().people,'현우');add(meta().cards,'gwageo-exam')}if(id==='ch02_ssanggi')add(meta().people,'쌍기');if(id==='ch02_reign_titles')add(meta().historicalEvents,'gwangjong-reign-titles');preloadScene(id);save()}
function memoryNote(sceneId){if(sceneId==='foundation'){if(run().initialMemory==='918')return '<div class="memory-note correct-memory">당신의 기억이 맞았습니다. · 918년 고려 건국</div>';if(run().initialMemory==='936')return '<div class="memory-note">918년과 936년을 헷갈리고 있어요. 936년의 의미는 곧 다시 만나게 됩니다.</div>';return '<div class="memory-note">방금 경험한 장면이 새로운 기억이 되었습니다. · 918년 고려 건국</div>'}if(sceneId==='outfit_gift')return '<div class="memory-note item-memory">아이템 · 고려 평민복 착용<br><small>현대 복장은 보관 중입니다.</small></div>';const story=STORIES[sceneId];if(story?.historyCard)return `<div class="memory-note history-memory"><small>[HISTORY DISCOVERED]</small><strong>${esc(story.historyCard.title)}</strong><br><span>${esc(story.historyCard.body)}</span></div>`;if(story?.mysteryKey)return '<div class="memory-note mystery-memory"><small>[알 수 없는 기억]</small><strong>???</strong></div>';return ''}
function statusSnapshot(sceneId){if(sceneId!=='status')return '';const r=run();return `<div class="first-status"><span><small>신분</small>${r.status}</span><span><small>직업</small>${r.job}</span><span><small>재산</small>${r.stats.wealth}냥</span><span><small>명성</small>${r.stats.fame}</span><span><small>체력</small>${r.stats.health}</span><span><small>지식</small>${r.stats.knowledge}</span></div>`}
function resultChips(p){const stats=Object.entries(p.statChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${statNames[k]} ${v>0?'+':''}${v}${k==='wealth'?'냥':''}</span>`);const relations=Object.entries(p.relationshipChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${relationNames[k]} ${v>0?'+':''}${v}</span>`);const trust=Object.entries(p.trustChanges||{}).filter(([,v])=>v!==0).map(([k,v])=>`<span>${relationNames[k]} 신뢰 ${v>0?'+':''}${v}</span>`);if(p.job&&p.job!=='없음')stats.push(`<span>새 직업 · ${esc(p.job)}</span>`);if(p.lifePath)stats.push(`<span>삶의 방향 · ${esc(p.lifePath)}</span>`);return [...stats,...relations,...trust].join('')}
function conversationEntries(source,p){if(p)return p.resultDialogues?.length?p.resultDialogues:[dialogueLine('player','serious',p.label),dialogueLine('narrator','neutral',p.result,'narration')];return source.dialogues?.length?source.dialogues:[dialogueLine('narrator','neutral',source.dialogue,'narration')]}
function stagePortrait(entry,side,active){const portraitId=resolvedPortraitId(entry);if(!portraitId)return '';const asset=PORTRAITS[portraitId];if(!asset?.src)return '';return `<img class="stage-character stage-${side} ${active?'active':'listening'}" data-portrait="${esc(portraitId)}" src="${esc(asset.src)}" alt="${esc(entry.characterName||'주인공')} ${esc(entry.expression)} 표정">`}
function characterStage(visible,source,complete,p,assetId){const art=ASSETS[assetId],embeddedIds=new Set(art?.embeddedCharacterIds||[]);if(art?.embeddedCharacters&&!embeddedIds.size)return '';const current=visible.at(-1),latestNpc=[...visible].reverse().find(entry=>entry.speakerType==='npc'),latestPlayer=[...visible].reverse().find(entry=>entry.speakerType==='player'||entry.speakerType==='thought');let player=latestPlayer;if(complete&&source.choices&&!p)player=dialogueLine('player','thinking','');const npc=latestNpc||((complete&&source.choices&&!p)?[...source.dialogues].reverse().find(entry=>entry.speakerType==='npc'):null);const activeId=current?.speakerType==='narration'?null:(current?.speakerType==='thought'?'player':current?.characterId);const portraits=[embeddedIds.has(npc?.characterId)?'':stagePortrait(npc,'left',activeId===npc?.characterId),embeddedIds.has(player?.characterId)?'':stagePortrait(player,'right',activeId==='player'||(!activeId&&complete&&source.choices&&!p))].join('');return portraits?`<div class="character-stage" aria-hidden="true">${portraits}</div>`:''}
function dialogueBubble(entry,index){if(entry.speakerType==='thought')return `<div class="monologue" data-dialogue-index="${index}" data-speaker-type="thought" data-expression="${esc(entry.expression)}"><span>속마음</span><p>${esc(entry.dialogue)}</p></div>`;if(entry.speakerType==='narration')return `<div class="narration-line" data-dialogue-index="${index}" data-speaker-type="narration"><p>${esc(entry.dialogue)}</p></div>`;const side=entry.speakerType==='player'?'player':'npc';return `<div class="message-row ${side}" data-dialogue-index="${index}" data-speaker-type="${side}" data-expression="${esc(entry.expression)}"><div class="bubble-stack"><span class="character-name">${esc(entry.characterName)}</span><p class="speech-bubble">${esc(entry.dialogue)}</p></div></div>`}
function choiceButtons(source,r){return `<div class="choice-dock"><span>나의 선택</span><div class="choices">${source.choices.map((c,i)=>{const available=choiceAvailable(r,c);return `<button class="choice ${available?'':'locked-choice'}" data-choice="${i}" ${available?'':'disabled'}><span>${esc(c.label)}</span>${c.hint?`<small>${available?'':icon('lock')+' '}${esc(c.hint)}</small>`:''}</button>`}).join('')}</div></div>`}
function game(){const r=run(),s=STORIES[r.storyId],p=r.pending;if(!s&&!p)return home();const source=p?STORIES[p.sourceSceneId]:s,assetId=p?p.resultIllustrationId:source.illustrationId,entries=conversationEntries(source,p),cursor=Math.max(1,Math.min(r.dialogueCursor||1,entries.length)),complete=cursor>=entries.length,visibleCount=complete&&source.choices&&!p?2:3,visibleStart=Math.max(0,cursor-visibleCount),visible=entries.slice(visibleStart,cursor),art=ASSETS[assetId],steps=chapterScenes(r.currentChapter).length,effect=source.sceneEffect?`effect-${source.sceneEffect}`:'',cinematic=source.sceneEffect==='blackout',style=cinematic?'':assetStyle(assetId),continueLabel=source.continueLabel||(cinematic?'천천히 눈을 뜬다':source.quizId?'🧠 기억을 더듬는다':source.nextStoryId==='voice'?'잠이 든다':'다음 이야기'),cinematicStatus=source.cinematicStatus||'의식을 되찾는 중…',cinematicSub=source.cinematicSub||'소리만 들린다. 아직 눈을 뜨지 못했다.';return `<section class="game conversation-game ${art?.src?'has-art':'needs-art'} ${art?.embeddedCharacters?'embedded-art':'layered-art'} ${effect} ${cinematic?'cinematic-black':''}" data-illustration="${esc(assetId)}" style="${style}">${cinematic?'':assetNotice(assetId)}<div class="scene-scrim"></div><div class="game-header"><button class="glass" data-nav="home">‹ &nbsp; 이야기 나가기</button><span class="glass">CH.${chapter().number} &nbsp; ${source.year}년</span><button class="glass" data-action="status">내 상태</button></div><div class="game-stats"><span>♡ &nbsp; 체력 ${r.stats.health}</span><span>◇ &nbsp; 지식 ${r.stats.knowledge}</span><span>◉ &nbsp; ${r.stats.wealth}냥</span></div><div class="scene-title"><small>${esc(source.location)}</small><h2>${p?'내 선택으로 달라진 장면':esc(source.title)}</h2></div>${characterStage(visible,source,complete,p,assetId)}<section class="conversation-panel" aria-label="대화"><div class="dialogue-log">${visible.map((entry,i)=>dialogueBubble(entry,visibleStart+i)).join('')}</div><div class="dialogue-step"><span>${cursor} / ${entries.length}</span>${!complete?(source.autoAdvanceDelays?`<span class="cinematic-wait">${esc(cinematicStatus)}</span>`:'<button class="advance-dialogue" data-action="advance-dialogue">탭하여 계속 <b>›</b></button>'):''}</div>${complete&&!p?memoryNote(source.sceneId)+statusSnapshot(source.sceneId):''}${complete?(p?`<div class="result-chips">${resultChips(p)}</div><button class="primary next" data-action="result-next">이야기 계속</button>`:source.choices?choiceButtons(source,r):`<button class="primary next" data-action="next">${continueLabel}</button>`):''}<div class="conversation-sub">${p?'선택 → 대사 → 반응 → 결과가 저장됩니다.':cinematic?esc(cinematicSub):'최근 대화만 남겨 장면에 집중할 수 있어요.'}</div></section><div class="chapter-progress">${Array.from({length:steps},(_,i)=>`<i class="${progress()>i/steps*100?'on':''}"></i>`).join('')}</div></section>`}

function activeQuestion(){return QUESTIONS.find(q=>q.questionId===(quizMode==='story'?run().activeQuestionId:reviewQuestionId))}
function quiz(){const q=activeQuestion();if(!q)return study();const selected=quizMode==='story'?run().questionAnswer:reviewAnswer,done=selected!==null,correct=done&&selected===q.answer,asset=ASSETS[q.relatedIllustrationId],resume=STORIES[q.resumeStoryId],isFinal=Boolean(resume?.completeChapter&&!resume?.nextStoryId),examLabel=q.isOfficial?`실제 기출 · 제${q.examRound}회 ${q.examLevel||'기본'} ${q.questionNumber}번`:(q.examType||'한능검 기출 유형 · 자체 제작');return pageHeader(quizMode==='story'?'방금 경험한 역사, 시험에서는?':'틀린 장면 다시 보기','REMEMBER THE MOMENT')+`<section class="quiz"><div class="story-test-head"><span class="badge">${q.questionId==='ch01-boss'?'BOSS QUESTION':q.isOfficial?'ACTUAL EXAM':'STORY TEST'} · ${q.difficulty}</span><span>CH.${CHAPTERS[q.chapterId].number} · ${esc(q.questionType)}</span></div><div class="quiz-memory ${asset?.src?'has-art':'needs-art'}" style="${assetStyle(q.relatedIllustrationId)}">${assetNotice(q.relatedIllustrationId,true)}<div><small>이 장면 기억나요?</small><b>${esc(asset?.label)}</b></div></div><div class="memory-trigger">🧠 ${q.questionId==='ch01-test-01'?'기억을 더듬는다':'방금 들은 이야기가 익숙하다.'}</div>${q.passage?`<div class="passage">${esc(q.passage)}</div>`:''}<h2>${esc(q.question)}</h2><span class="text-btn">${esc(examLabel)}</span>${q.choices.map((x,i)=>`<button class="choice ${done&&i===q.answer?'correct':done&&i===selected?'wrong':''}" data-answer="${i}" ${done?'disabled':''}><span>${['①','②','③','④','⑤'][i]} &nbsp; ${esc(x)}</span>${done&&i===q.answer?'✓':''}</button>`).join('')}${done?`<div class="feedback" role="status"><h3>${correct?'기억이 선명해졌다.':'기억이 흐릿하다.'}</h3><p>${esc(q.explanation)}</p><div class="keywords">${q.examKeywords.map(x=>`<span>${esc(x)}</span>`).join('')}</div><p class="feedback-reward">${correct?`정답 · 지식 +${q.rewardKnowledge||2}`:'오답노트 +1 · 이야기는 계속됩니다.'}</p></div><button class="primary next" data-action="quiz-next">${quizMode==='review'?'오답노트로 돌아가기':isFinal?'CHAPTER 결과 보기':'다시 이야기로 돌아가기'}</button>`:''}</section>`}

function study(){let body='';if(studyTab==='review'){body=meta().wrongQuestionIds.length?meta().wrongQuestionIds.map(id=>{const q=QUESTIONS.find(x=>x.questionId===id);if(!q)return '';return `<div class="list-row"><div><span class="badge">${meta().reviewedQuestionIds.includes(id)?'복습 완료':'복습 필요'}</span><h3>${esc(q.question.split('\n')[0])}</h3><p>${q.examKeywords.slice(0,3).map(esc).join(' · ')}</p></div><button class="primary" data-review="${q.questionId}">다시 풀기</button></div>`}).join(''):`<div class="empty">아직 틀린 역사가 없어요.<br><small>스토리 중간 문제를 풀면 복습할 내용이 이곳에 모여요.</small></div>`}if(studyTab==='quiz')body=QUESTIONS.map((q,i)=>`<div class="list-row"><div><span class="eyebrow">${q.questionId==='ch01-boss'?'BOSS QUESTION':`STORY TEST 0${i+1}`}</span><h3>${esc(q.question.split('\n')[0])}</h3><p>${esc(q.questionType)} · ${esc(q.difficulty)} · ${meta().questionRecords[q.questionId]?(meta().questionRecords[q.questionId].lastCorrect?'최근 정답':'다시 기억하기'):'아직 만나지 못했어요'}</p></div><button class="primary" data-practice="${q.questionId}">문제 풀기</button></div>`).join('');if(studyTab==='timeline')body=[['900','견훤, 후백제 건국','완산주를 중심으로 후백제를 세웠습니다.'],['901','궁예, 후고구려 건국','이후 국호를 마진, 태봉으로 바꾸었습니다.'],['918','고려 건국','왕건이 신하들의 추대를 받아 왕위에 올랐습니다.'],['935','신라의 항복','경순왕이 고려에 항복했습니다.'],['936','후삼국 통일','고려가 후백제를 무너뜨리고 통일했습니다.']].map(([y,t,d])=>`<div class="list-row timeline-row"><div><span class="eyebrow">${y}년</span><h3>${t}</h3><p>${d}</p></div></div>`).join('');if(studyTab==='cards')body=`<div class="collection">${['고려 건국','왕건','궁예','견훤','광종','노비안검법'].map((x,i)=>{const unlocked=i===0?meta().cards.length>0:meta().people.includes(x);return `<div class="collect ${unlocked?'':'locked'}">${icon(unlocked?'study':'lock')}<h3>${unlocked?x:'아직 만나지 못한 역사'}</h3><p>${unlocked?'CH.01에서 직접 만난 역사':'이야기를 진행하면 열립니다'}</p>${unlocked&&i===0?'<button class="text-btn" data-nav="history">자세히 보기 ›</button>':''}</div>`}).join('')}</div>`;return pageHeader('살아본 순간을, 오래 기억하도록','MY STUDY')+`<div class="tabs">${[['review','오답노트'],['quiz','시험 문제'],['timeline','역사 연표'],['cards','역사 도감']].map(([id,x])=>`<button data-study="${id}" class="${studyTab===id?'selected':''}">${x}</button>`).join('')}</div>${body}`}
function history(){return pageHeader('방금, 당신이 경험한 역사','HISTORY DISCOVERED')+`<article class="history-card"><span class="eyebrow">역사 카드 001 · 고려</span><h2>918년<br>${HISTORY.title}</h2><img src="goryeo.png" alt="고려 시대 전경"><p>${HISTORY.summary}</p><div class="info-note">주인공과 도윤의 이야기는 창작입니다. 시험 화면에서 ‘실제 기출’로 표시된 문항은 사용자 제공 한국사능력검정시험 문제지·정답표를 연결했으며, ‘실전 유형 연습’ 문항은 챕터 학습 범위에 맞춘 자체 제작 문제입니다.</div><h3>시험에서는 이렇게 기억하세요</h3><div class="keywords">${HISTORY.examKeywords.map(x=>`<span>${x}</span>`).join('')}</div><p class="source-link"><a href="https://contents.history.go.kr/mobile/kc/view.do?code=kc_age_10&levelId=kc_i101800" target="_blank" rel="noopener noreferrer">역사 내용 참고 · 국사편찬위원회 우리역사넷</a></p></article>`}
function records(){const records=Object.values(meta().questionRecords),attempts=records.reduce((n,r)=>n+r.attempts,0),r=mainRun(),info=mainChapter();return pageHeader('한 걸음씩, 나의 한국사','MY JOURNEY')+`<div class="stats-grid">${[['현재 챕터 진행률',progressFor(r)+'%'],['누적 문제 정답률',attempts?cumulativeAccuracy()+'%':'—'],['풀어본 문제',Object.keys(meta().questionRecords).length+' / '+QUESTIONS.length],['오답 기록',meta().wrongQuestionIds.length+'개'],['발견한 역사 사건',meta().historicalEvents.length],['완료한 챕터',meta().completedChapters.length+'개']].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div><div class="section-title"><h2>현재 고려 인생 · CH.${info.number}</h2><button class="text-btn" data-action="status">상태창 보기 ›</button></div><div class="list-row"><div><h3>${r.status} · ${esc(r.job)}</h3><p>${esc(info.subtitle)} · ${esc(r.route||'아직 정하지 않음')} · 최고 재산 ${r.peakWealth}냥</p></div><span class="badge">${r.completed?'챕터 완료':r.started?'이야기 진행 중':'시작 전'}</span></div><div class="list-row"><div><h3>누적 수집 기록</h3><p>인물 ${meta().people.length}명 · 카드 ${meta().cards.length}장 · 엔딩 ${meta().endings.length}개 · 업적 ${meta().achievements.length}개</p></div></div><div class="list-row"><div><h3>현재 메인 챕터 선택 ${r.choices.length}개</h3><p>${r.choices.length?r.choices.slice(-3).map(c=>esc(c.label)).join(' · '):'아직 선택한 이야기가 없습니다.'}</p></div></div>${r.completed?'<button class="primary next" data-chapter-result="'+r.currentChapter+'">나의 챕터 결과 보기</button>':''}${r.started?'<button class="text-btn restart-link" data-action="restart-current">현재 챕터 다시하기</button>':''}`}
function resultRun(chapterId){if(!resultChapterId)return run();const record=latestRunRecord(chapterId);return {...INITIAL_RUN(chapterId,record?.finalRun),...record?.finalRun,currentChapter:chapterId,completed:true,questionResults:{...record?.questionResults},choices:(record?.choices||[]).map(choice=>({...choice}))}}
function scoreHistory(chapterId,current){const record=meta().chapterRecords[chapterId],first=record?.firstRun?.questionScore?.correct??current,best=record?.bestQuestionScore??current;return `<div class="run-score-history"><span><small>이번 기록</small><b>${current} / ${CHAPTERS[chapterId].questionCount}</b></span><span><small>최고 기록</small><b>${best} / ${CHAPTERS[chapterId].questionCount}</b></span><span><small>첫 기록</small><b>${first} / ${CHAPTERS[chapterId].questionCount}</b></span></div>`}
function resultFooter(chapterId){if(run().mode==='replay'&&run().completed&&!resultChapterId)return `<div class="replay-complete-actions"><button class="primary next" data-action="view-replay-result" data-chapter="${chapterId}">챕터 결과 보기</button><button class="secondary full" data-action="return-replay-home">눈떠보니 고려로 돌아가기</button><button class="text-btn home-link" data-action="current-main">현재 이야기 이어하기</button></div>`;if(resultChapterId)return `<button class="primary next" data-action="request-replay" data-chapter="${chapterId}">챕터 다시 플레이</button><button class="text-btn home-link" data-nav="home">눈떠보니 고려로 돌아가기</button>`;const next=chapterOrder()[chapterOrder().findIndex(info=>info.chapterId===chapterId)+1],nextLabel=next?`CH.${next.number} ${next.title}`:'눈떠보니 고려로 돌아가기';return `<button class="primary next" data-nav="${next?'teaser':'home'}">${nextLabel}</button><button class="secondary full" data-action="request-replay" data-chapter="${chapterId}">다른 선택으로 다시 살아보기</button><button class="text-btn home-link" data-nav="home">홈으로 돌아가기</button>`}
function completeCh01(){const r=resultRun('ch01'),total=chapterQuestions('ch01').length,correct=correctFor(r,'ch01'),missed=total-correct,confused=r.initialMemory==='936'?'918년 ↔ 936년':missed?'후삼국 사건의 순서와 인물 연결':'없음',replay=run().mode==='replay'&&run().completed&&!resultChapterId;return `<section class="complete"><div class="seal">史</div><div class="eyebrow complete-label">CHAPTER 01 ${replay?'REPLAY COMPLETE':'COMPLETE'}</div><h1>${replay?'CH.01 재플레이 완료':'새로운 나라'}</h1><p>${r.route==='merchant'?'상단에서 일하며 고려의 첫날을 살아냈습니다.':r.route==='village'?'마을 사람들과 함께 고려의 첫날을 살아냈습니다.':r.route==='royal'?'왕건을 향한 특별한 뜻을 품고 고려의 첫날을 살아냈습니다.':'도윤과 송악으로 향하며 고려의 첫날을 살아냈습니다.'}</p><div class="history-flow"><span>견훤<br><b>후백제</b></span><i>→</i><span>궁예<br><b>후고구려</b></span><i>→</i><span>왕건<br><b>918 고려</b></span><i>→</i><span>935 신라 항복<br><b>936 통일</b></span></div>${r.initialMemory==='936'?'<div class="memory-note">처음에 헷갈렸던 936년은 후삼국 통일의 해였습니다.</div>':''}<h2 class="result-title">나의 첫 번째 고려 생활</h2><div class="stats-grid">${[['선택한 삶',r.job],['재산',r.stats.wealth+'냥'],['명성',r.stats.fame],['지식',r.stats.knowledge],['도윤 관계',r.relations.doyun],['경험한 사건','고려 건국']].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div>${scoreHistory('ch01',correct)}<div class="chapter-learning"><div><small>CH.01 문제</small><strong>${correct} / ${total} 정답</strong></div><div><small>정답률</small><strong>${Math.round(correct/total*100)}%</strong></div><div><small>헷갈리는 개념</small><strong>${confused}</strong></div><div><small>오답</small><strong>${missed}개</strong></div></div>${missed?'<button class="secondary full" data-action="review-wrong">틀린 문제 다시 풀기</button>':''}${resultFooter('ch01')}</section>`}
function completeCh02(){const r=resultRun('ch02'),total=chapterQuestions('ch02').length,correct=correctFor(r,'ch02'),missed=total-correct,memory=meta().knowledgeMemory['ch02-nobi-purpose'],replay=run().mode==='replay'&&run().completed&&!resultChapterId;return `<section class="complete ch02-complete"><div class="seal">王</div><div class="eyebrow complete-label">CHAPTER 02 ${replay?'REPLAY COMPLETE':'COMPLETE'}</div><h1>${replay?'CH.02 재플레이 완료':'왕의 나라'}</h1><p>길상의 신분 회복과 현우의 시험을 곁에서 지켜보며, 광종의 정책이 친구들의 삶을 어떻게 바꾸는지 경험했습니다.</p><div class="history-flow policy-flow"><span>956<br><b>노비안검법</b></span><i>→</i><span>958<br><b>과거제</b></span><i>→</i><span>광덕 · 준풍<br><b>독자적 연호</b></span><i>→</i><span>호족 견제<br><b>왕권 강화</b></span></div>${memory&&!memory.correct?'<div class="memory-note">처음의 선택과 달리, 노비안검법은 호족의 기반을 줄여 왕권 강화에 도움을 주었습니다.</div>':''}<h2 class="result-title">나의 두 번째 고려 생활</h2><div class="stats-grid">${[['삶의 방향',r.lifePath||r.job],['재산',r.stats.wealth+'냥'],['도윤 관계',r.relations.doyun],['도윤 신뢰',r.trust.doyun],['현우 관계',r.relations.hyunwoo],['현우 신뢰',r.trust.hyunwoo]].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${v}</strong></div>`).join('')}</div>${scoreHistory('ch02',correct)}<div class="chapter-learning"><div><small>CH.02 문제</small><strong>${correct} / ${total} 정답</strong></div><div><small>정답률</small><strong>${Math.round(correct/total*100)}%</strong></div><div><small>핵심 흐름</small><strong>광종 → 호족 견제 → 왕권 강화</strong></div><div><small>함께 겪은 일</small><strong>${r.sharedEvents.length}개 저장</strong></div></div>${missed?'<button class="secondary full" data-action="review-wrong">틀린 문제 다시 풀기</button>':''}${resultFooter('ch02')}</section>`}
function completeCh03(){const r=resultRun('ch03'),total=chapterQuestions('ch03').length,officialCount=chapterQuestions('ch03').filter(q=>q.isOfficial).length,correct=correctFor(r,'ch03'),missed=total-correct,replay=run().mode==='replay'&&run().completed&&!resultChapterId;return `<section class="complete ch03-complete"><div class="seal">制</div><div class="eyebrow complete-label">CHAPTER 03 ${replay?'REPLAY COMPLETE':'COMPLETE'}</div><h1>${replay?'CH.03 재플레이 완료':'나라의 틀'}</h1><p>상단이 겪은 지방의 문제에서 출발해, 성종이 고려를 움직일 제도를 세우는 과정을 삶으로 경험했습니다.</p><h2 class="result-title">이번에 경험한 역사</h2><div class="history-flow policy-flow"><span>성종<br><b>유교 정치</b></span><i>→</i><span>최승로<br><b>시무 28조</b></span><i>→</i><span>12목<br><b>지방관 파견</b></span><i>→</i><span>국자감<br><b>인재 교육</b></span></div><div class="chapter-learning"><div><small>중앙 집권</small><strong>지방을 직접 다스리는 틀</strong></div><div><small>정치 질서</small><strong>유교 통치 체제</strong></div><div><small>지방 제도</small><strong>12목 지방관 파견</strong></div><div><small>교육 기관</small><strong>국자감</strong></div></div><h2 class="result-title">당신의 고려 이야기</h2><div class="stats-grid">${[['도윤의 꿈','도윤상단의 완성'],['오랜 인연','현우와 다시 만남'],['겪은 문제','지방 사회의 현실'],['남은 유산',r.doyunLegacy?.name||'도윤상단'],['도윤',r.characterStates?.doyun?.isAlive===false?'긴 삶을 마침':'기억 속의 친구'],['상단의 선택',r.importantChoices?.ch03_policy_choice||r.choices.find(c=>c.scene==='ch03_policy_choice')?.importantChoice||'함께 고민함']].map(([t,v])=>`<div class="stat-box"><small>${t}</small><strong>${esc(v)}</strong></div>`).join('')}</div>${scoreHistory('ch03',correct)}<div class="chapter-learning"><div><small>CH.03 문제</small><strong>${correct} / ${total} 정답</strong></div><div><small>정답률</small><strong>${Math.round(correct/total*100)}%</strong></div><div><small>실제 기출</small><strong>${officialCount}개 연계</strong></div><div><small>오답</small><strong>${missed}개</strong></div></div>${missed?'<button class="secondary full" data-action="review-wrong">틀린 문제 다시 풀기</button>':''}${resultFooter('ch03')}</section>`}
function complete(){const id=resultChapterId||run().currentChapter;return id==='ch03'?completeCh03():id==='ch02'?completeCh02():completeCh01()}
function teaser(){if(run().currentChapter==='ch03'&&run().completed){const asset=ASSETS['ch04-khitan-teaser'];return `<section class="hero teaser ${asset?.src?'has-art':'needs-art'}" style="${assetStyle('ch04-khitan-teaser')}">${assetNotice('ch04-khitan-teaser')}<div class="hero-content teaser-content"><span class="pill">CHAPTER 04 · NEXT</span><h2>북쪽에서 온 적</h2><p>“북쪽에서 심상치 않은 소식이<br>들려오기 시작했다.”<br><br><b>거란의 침입</b></p><button class="primary teaser-button" data-nav="home">나의 이야기로 돌아가기</button></div></section>`}if(run().currentChapter==='ch02'&&run().completed){const asset=ASSETS['ch03-teaser'];return `<section class="hero teaser ${asset?.src?'has-art':'needs-art'}" style="${assetStyle('ch03-teaser')}">${assetNotice('ch03-teaser')}<div class="hero-content teaser-content"><span class="pill">CHAPTER 03 · UNLOCKED</span><h2>나라의 틀</h2><p>“나라를 다스리는 데 필요한 일을<br>스물여덟 가지로 정리하였습니다.”<br><br><b>시무 28조 · 성종 · 최승로</b></p><button class="primary teaser-button" data-action="start-chapter" data-chapter="ch03">CH.03 시작하기</button></div></section>`}const asset=ASSETS['chapter-02-teaser'];return `<section class="hero teaser ${asset?.src?'has-art':'needs-art'}" style="${assetStyle('chapter-02-teaser')}">${assetNotice('chapter-02-teaser')}<div class="hero-content teaser-content"><span class="pill">CHAPTER 02 · UNLOCKED</span><h2>왕의 나라</h2><p>“본래 양인이었던 자를 노비로 삼은 기록이 있군.”<br>왕은 왜 자신의 사람들을 풀어주었을까?<br><br><b>광종 · 노비안검법 · 과거제</b></p><button class="primary teaser-button" data-action="start-ch02">CH.02 시작하기</button></div></section>`}
function chapterDiscoveryCount(id){const eventIds=new Set(chapterQuestions(id).map(q=>q.relatedHistoricalEventId).filter(Boolean));return [...eventIds].filter(eventId=>meta().historicalEvents.includes(eventId)).length}
function chapterDetailModal(id){const info=CHAPTERS[id],status=chapterStatus(id),record=latestRunRecord(id),score=record?.questionScore||questionScore(id,record?.questionResults),main=mainRun(),pct=chapterProgress(id),completed=status==='COMPLETED';let actions='';if(completed)actions=`<div class="chapter-detail-stats"><span><small>선택</small><b>${record?.choices?.length||0}개</b></span><span><small>정답률</small><b>${score.total?score.percent+'%':'—'}</b></span><span><small>발견한 역사</small><b>${chapterDiscoveryCount(id)}개</b></span><span><small>플레이 회차</small><b>${meta().chapterRuns[id]?.length||1}회</b></span></div><button class="primary full" data-action="request-replay" data-chapter="${id}">챕터 다시 플레이</button><button class="secondary full" data-action="view-chapter-result" data-chapter="${id}">챕터 결과 보기</button>`;else if(status==='CURRENT'&&info.implemented)actions=main.currentChapter===id&&main.started?`<div class="current-progress"><span>현재 진행</span><b>${pct}%</b><div class="progress"><span style="width:${pct}%"></span></div></div><button class="primary full" data-action="continue-chapter" data-chapter="${id}">이어서 플레이</button><button class="secondary full" data-action="restart-current" data-chapter="${id}">처음부터 다시</button>`:`<button class="primary full" data-action="start-chapter" data-chapter="${id}">CHAPTER ${info.number} 시작하기</button>`;else if(status==='CURRENT')actions='<button class="secondary full" disabled>다음 챕터 준비 중</button>';return `<div class="modal-overlay chapter-sheet-overlay"><section class="modal chapter-sheet" role="dialog" aria-modal="true" aria-label="CHAPTER ${info.number} 상세"><div class="sheet-handle" aria-hidden="true"></div><header><div><span class="eyebrow">CHAPTER ${info.number}</span><h2>${esc(info.subtitle)}</h2></div><button class="close" data-action="close" aria-label="닫기">×</button></header><p class="chapter-sheet-status">${completed?'완료한 이야기':status==='CURRENT'?(main.currentChapter===id&&main.started?'현재 진행':'다음 이야기'):'잠긴 이야기'}</p>${actions}<button class="text-btn sheet-cancel" data-action="close">취소</button></section></div>`}
function modalHTML(){
  if(modal&&typeof modal==='object'){
    if(modal.type==='chapter')return chapterDetailModal(modal.chapterId);
    if(modal.type==='replay-confirm'){const info=CHAPTERS[modal.chapterId];return `<div class="modal-overlay"><section class="modal confirm-modal" role="dialog" aria-modal="true" aria-label="CH.${info.number} 재플레이 확인"><h2>CH.${info.number}을 다시 플레이할까요?</h2><p class="lead modal-copy">다른 선택으로 이 챕터를 다시 경험할 수 있어요.<br><br>이미 완료한 이후 챕터의 진행 기록은 유지됩니다.<br>이번 재플레이에서 선택한 내용은 새로운 회차 기록으로 저장됩니다.</p><div class="modal-actions"><button class="glass" data-action="close">취소</button><button class="primary" data-action="confirm-replay" data-chapter="${info.chapterId}">다시 플레이</button></div></section></div>`}
    if(modal.type==='restart-current'){const info=CHAPTERS[modal.chapterId],previous=chapterOrder()[chapterOrder().findIndex(item=>item.chapterId===modal.chapterId)-1];return `<div class="modal-overlay"><section class="modal confirm-modal" role="dialog" aria-modal="true" aria-label="CH.${info.number} 다시 시작"><h2>CH.${info.number}을 처음부터 다시 시작할까요?</h2><p class="lead modal-copy">${previous?`CH.${previous.number}에서 이어온 직업·스탯·관계는 유지하고 현재 CH.${info.number} 진행만 초기화합니다.`:'현재 메인 이야기의 CH.01 진행을 처음으로 되돌립니다.'}</p><div class="modal-actions"><button class="glass" data-action="close">취소</button><button class="primary" data-action="confirm-restart-current">처음부터 다시</button></div><p class="data-policy">완료한 챕터 회차·오답·역사 카드·업적 등 누적 기록은 삭제하지 않습니다.</p></section></div>`}
    if(modal.type==='restart-episode')return `<div class="modal-overlay"><section class="modal confirm-modal" role="dialog" aria-modal="true" aria-label="고려편 처음부터 다시 시작"><h2>고려편을 처음부터 다시 시작할까요?</h2><p class="lead modal-copy">현재 메인 이야기를 CH.01 첫 장면으로 되돌립니다.<br>완료 회차와 누적 학습 기록은 보존됩니다.</p><div class="modal-actions"><button class="glass" data-action="close">취소</button><button class="primary" data-action="confirm-restart-episode">처음부터 다시하기</button></div></section></div>`
  }
  const r=run();return `<div class="modal-overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="내 상태"><header><h2>나의 상태 · CH.${chapter().number}</h2><button class="close" data-action="close" aria-label="닫기">×</button></header><p class="lead modal-copy">${r.status} · ${r.job}</p><div class="stats-grid">${Object.entries(r.stats).map(([k,v])=>`<div class="stat-box"><small>${statNames[k]}</small><strong>${v}${k==='wealth'?'냥':''}</strong></div>`).join('')}</div><h3>함께 살아가는 사람들</h3>${Object.entries(r.relations).map(([k,v])=>`<div class="list-row"><span>${relationNames[k]||k}</span><span>${v} <small>/ 100</small></span></div>`).join('')}<p class="text-btn">현재 챕터 진행과 관계는 선택할 때마다 자동 저장됩니다.</p></section></div>`}
function renderContent(){return({home,era:eras,game,quiz,study,records,complete,teaser,history}[screen]||home)()}
function syncCinematicTimeline(){if(cinematicTimer&&typeof clearTimeout==='function')clearTimeout(cinematicTimer);cinematicTimer=null;const r=run(),source=STORIES[r.storyId];if(screen!=='game'||r.pending||!source?.autoAdvanceDelays||typeof setTimeout!=='function')return;const entries=conversationEntries(source,null),cursor=Math.max(1,Math.min(r.dialogueCursor||1,entries.length));if(cursor>=entries.length)return;const sceneId=r.storyId,dialogueKey=r.dialogueSceneId,delay=source.autoAdvanceDelays[cursor-1]||850;cinematicTimer=setTimeout(()=>{if(screen!=='game'||run().storyId!==sceneId||run().dialogueSceneId!==dialogueKey)return;run().dialogueCursor=Math.min(entries.length,cursor+1);save();render()},delay)}
function render(){$('#app').innerHTML=shell(renderContent());syncCinematicTimeline();if(modal)setTimeout(()=>$('.modal button')?.focus(),0)}
function navigate(to){screen=to;modal=null;if(to!=='complete')resultChapterId=null;render();window.scrollTo(0,0)}
function play(){run().started=true;if(run().completed)return navigate('complete');if(run().activeQuestionId){quizMode='story';screen='quiz'}else screen='game';enterStory();render();window.scrollTo(0,0)}
function playMain(){if(state.mainRun)restoreMainRun(state);resultChapterId=null;save();const info=CHAPTERS[run().currentChapter];if(!info?.implemented&&!run().completed)return toast(`CH.${info?.number||''}은 아직 준비 중입니다.`);return play()}
function openChapterCard(id){const status=chapterStatus(id),info=CHAPTERS[id];if(status==='LOCKED'){const order=chapterOrder(),index=order.findIndex(item=>item.chapterId===id),previous=order[index-1];return toast(`CH.${previous?.number||'이전 챕터'}을 완료하면 열립니다.`)}modal={type:'chapter',chapterId:id};render()}
function showChapterResult(id){if(!meta().completedChapters.includes(id))return;resultChapterId=id;modal=null;screen='complete';render();window.scrollTo(0,0)}
function startAvailableChapter(id){const info=CHAPTERS[id];if(!info?.implemented)return toast(`CH.${info?.number||''}은 아직 준비 중입니다.`);if(chapterStatus(id)!=='CURRENT')return;if(state.mainRun)restoreMainRun(state);if(run().currentChapter!==id||run().completed){if(!startChapter(state,id))return toast('이전 챕터를 완료하면 시작할 수 있습니다.')}preloadChapterCore(id);save();modal=null;screen='game';enterStory();render();window.scrollTo(0,0)}
function startQuestion(id){run().activeQuestionId=id;run().questionAnswer=null;quizMode='story';screen='quiz';save();render();window.scrollTo(0,0)}
function nextStory(){const s=STORIES[run().storyId];if(s?.quizId)return startQuestion(s.quizId);if(s?.completeChapter){finishChapter(state);save();return navigate('complete')}if(s?.nextStoryId){run().storyId=s.nextStoryId;enterStory();render()} }

document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled||!lockInput())return;if(b.dataset.chapterResult){e.stopPropagation?.();return showChapterResult(b.dataset.chapterResult)}if(b.dataset.nav)return navigate(b.dataset.nav);if(b.dataset.study){studyTab=b.dataset.study;return render()}if(b.dataset.choice!==undefined){applyChoice(state,run().storyId,Number(b.dataset.choice));const resultArt=ASSETS[run().pending?.resultIllustrationId];if(resultArt?.src)preloadImage(resultArt.src);save();return render()}if(b.dataset.answer!==undefined){const selected=Number(b.dataset.answer);if(quizMode==='story'){if(run().questionAnswer!==null)return;recordQuestion(state,run().activeQuestionId,selected)}else{if(reviewAnswer!==null)return;reviewAnswer=selected;recordQuestion(state,reviewQuestionId,selected);run().questionAnswer=null}save();return render()}if(b.dataset.review||b.dataset.practice){reviewQuestionId=b.dataset.review||b.dataset.practice;reviewAnswer=null;quizMode='review';return navigate('quiz')}switch(b.dataset.action){case'play':return play();case'current-main':return playMain();case'toggle-chapters':showAllChapters=!showAllChapters;return render();case'start-ch02':return startAvailableChapter('ch02');case'start-chapter':return startAvailableChapter(b.dataset.chapter);case'continue-chapter':{if(state.mainRun)restoreMainRun(state);modal=null;save();return play()}case'view-chapter-result':return showChapterResult(b.dataset.chapter);case'request-replay':modal={type:'replay-confirm',chapterId:b.dataset.chapter||resultChapterId||run().currentChapter};return render();case'confirm-replay':{const id=b.dataset.chapter;if(!beginReplay(state,id))return toast('완료한 챕터만 다시 플레이할 수 있습니다.');modal=null;resultChapterId=null;preloadChapterCore(id);save();screen='game';enterStory();render();window.scrollTo(0,0);return}case'view-replay-result':{const id=b.dataset.chapter||run().currentChapter;restoreMainRun(state);save();return showChapterResult(id)}case'return-replay-home':restoreMainRun(state);save();return navigate('home');case'restart-current':modal={type:'restart-current',chapterId:b.dataset.chapter||mainRun().currentChapter};return render();case'confirm-restart-current':if(state.mainRun)restoreMainRun(state);restartChapter(state);modal=null;resultChapterId=null;preloadChapterCore(run().currentChapter);save();return play();case'restart-episode':modal={type:'restart-episode'};return render();case'confirm-restart-episode':restartEpisodeMain(state);modal=null;resultChapterId=null;preloadChapterCore('ch01');save();return play();case'status':modal='status';return render();case'close':modal=null;return render();case'advance-dialogue':{const r=run(),source=r.pending?STORIES[r.pending.sourceSceneId]:STORIES[r.storyId],entries=conversationEntries(source,r.pending);r.dialogueCursor=Math.min(entries.length,(r.dialogueCursor||1)+1);if(!r.pending)applyDialogueMilestone(state,r.storyId,r.dialogueCursor);save();return render()}case'next':return nextStory();case'result-next':run().pending=null;enterStory();save();return render();case'quiz-next':{if(quizMode==='review'){reviewQuestionId=null;reviewAnswer=null;studyTab='review';return navigate('study')}const q=activeQuestion(),resume=STORIES[q.resumeStoryId];if(['complete','ch02_complete'].includes(q.resumeStoryId)&&!resume?.nextStoryId){finishChapter(state);save();return navigate('complete')}run().storyId=q.resumeStoryId;run().activeQuestionId=null;run().questionAnswer=null;enterStory();save();return navigate('game')}case'review-wrong':{const chapterId=resultChapterId||run().currentChapter,chapterIds=new Set(chapterQuestions(chapterId).map(q=>q.questionId)),resultData=resultChapterId?resultRun(chapterId):run(),first=meta().wrongQuestionIds.find(id=>chapterIds.has(id)&&resultData.questionResults[id]===false)||meta().wrongQuestionIds.find(id=>chapterIds.has(id))||meta().wrongQuestionIds[0];if(!first)return navigate('study');reviewQuestionId=first;reviewAnswer=null;quizMode='review';return navigate('quiz')}}if(b.dataset.chapter)return openChapterCard(b.dataset.chapter)});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){modal=null;render()}if(e.key==='Tab'&&modal){const items=[...document.querySelectorAll('.modal button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
if(document.modelContext){try{document.modelContext.registerTool({name:'get_history_progress',description:'Read this device’s Korean history game progress, current run, and cumulative learning record.',inputSchema:{type:'object',properties:{}},execute:async()=>({content:[{type:'text',text:JSON.stringify({storyId:run().storyId,completed:run().completed,stats:run().stats,accuracy:cumulativeAccuracy(),wrongAnswers:meta().wrongQuestionIds.length,completedRuns:meta().completedRuns})}]})})}catch{}}
preloadChapterCore(run().currentChapter||'ch01');save();render();
